#!/usr/bin/env python3
"""Zero-dependency loopback-only explorer and deterministic scenario CLI."""
import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import cast
from urllib.parse import urlsplit

from scenarios import DISCLAIMER, SCENARIOS, replay_result, run_scenario

ROOT = Path(__file__).resolve().parent
MAX_BODY = 262144
BODY_READ_TIMEOUT = 5.0


class Handler(BaseHTTPRequestHandler):
    def respond(self, status, body, content_type="application/json; charset=utf-8"):
        raw = body if isinstance(body, bytes) else json.dumps(body, allow_nan=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")
        self.end_headers()
        self.wfile.write(raw)

    def local_request(self):
        host = self.headers.get("Host", "")
        port = cast(ThreadingHTTPServer, self.server).server_port
        allowed = {f"127.0.0.1:{port}", f"localhost:{port}"}
        origin = self.headers.get("Origin")
        if host not in allowed or (origin is not None and origin != "http://" + host):
            self.respond(403, {"error": "Loopback same-origin requests only"})
            return False
        return True

    def do_GET(self):
        if not self.local_request():
            return
        route = urlsplit(self.path).path
        if route == "/api/scenarios":
            self.respond(200, {"disclaimer": DISCLAIMER, "scenarios": [
                {"id": key, "label": label, "description": description}
                for key, (label, description) in SCENARIOS.items()]})
        elif route in {"/", "/app.js", "/style.css"}:
            name, mime = {"/": ("index.html", "text/html"), "/app.js": ("app.js", "text/javascript"),
                          "/style.css": ("style.css", "text/css")}[route]
            self.respond(200, (ROOT / "web" / name).read_bytes(), mime + "; charset=utf-8")
        else:
            self.respond(404, {"error": "Not found"})

    def do_POST(self):
        if not self.local_request():
            return
        if self.path not in {"/api/run", "/api/replay", "/api/replay/explain"}:
            self.respond(404, {"error": "Not found"})
            return
        try:
            if self.headers.get_all("Transfer-Encoding") is not None:
                self.respond(400, {"error": "Transfer-Encoding is not supported; use Content-Length"})
                return
            lengths = self.headers.get_all("Content-Length", [])
            if not lengths:
                self.respond(411, {"error": "Content-Length is required"})
                return
            if len(lengths) != 1:
                self.respond(400, {"error": "Provide exactly one Content-Length"})
                return
            length_text = lengths[0].strip(" \t")
            if not length_text.isascii() or not length_text.isdecimal():
                self.respond(400, {"error": "Content-Length must contain ASCII decimal digits"})
                return
            # Compare decimal text before conversion, including arbitrarily
            # many leading zeroes, without Python's integer-string limit.
            length_text = length_text.lstrip("0") or "0"
            maximum = str(MAX_BODY)
            if (length_text == "0" or len(length_text) > len(maximum)
                    or (len(length_text) == len(maximum) and length_text > maximum)):
                self.respond(413, {"error": "Body must be between 1 and 262144 bytes"})
                return
            length = int(length_text)
            if self.headers.get("Content-Type", "").split(";")[0] != "application/json":
                self.respond(415, {"error": "Use application/json"})
                return
            previous_timeout = self.connection.gettimeout()
            self.connection.settimeout(BODY_READ_TIMEOUT)
            try:
                raw = self.rfile.read(length)
            except TimeoutError:
                self.respond(408, {"error": "Timed out waiting for the complete request body"})
                return
            finally:
                self.connection.settimeout(previous_timeout)
            if len(raw) != length:
                self.respond(400, {"error": "Request body is shorter than Content-Length"})
                return
            def reject_constant(value):
                raise ValueError("Non-finite JSON is not supported")
            value = json.loads(raw, parse_constant=reject_constant)
            if self.path == "/api/replay":
                result = replay_result(value)
            elif self.path == "/api/replay/explain":
                from replay_explain import explain_replay
                result = explain_replay(value)
            else:
                if not isinstance(value, dict) or set(value) != {"scenario", "include_approval", "include_ack"}:
                    raise ValueError("Provide scenario and both fixture switches")
                if not isinstance(value["scenario"], str):
                    raise ValueError("Scenario must be a string")
                result = run_scenario(**value)
            self.respond(200, result)
        except (ValueError, TypeError, KeyError, RecursionError) as exc:
            self.respond(400, {"error": str(exc)[:200]})


def main():
    parser = argparse.ArgumentParser(description=DISCLAIMER)
    commands = parser.add_subparsers(dest="command", required=True)
    serve = commands.add_parser("serve", help="Loopback-only browser UI")
    serve.add_argument("--port", type=int, default=8765)
    run = commands.add_parser("run", help="Export a fixed synthetic case as JSON")
    run.add_argument("scenario", choices=SCENARIOS)
    run.add_argument("--without-approval", action="store_true")
    run.add_argument("--without-ack", action="store_true")
    replay = commands.add_parser("replay", help="Recompute and compare a local JSON export")
    replay.add_argument("file", type=Path)
    replay.add_argument("--explain", action="store_true",
                        help="Report up to 32 literal differing JSON paths")
    args = parser.parse_args()
    if args.command == "serve":
        with ThreadingHTTPServer(("127.0.0.1", args.port), Handler) as server:
            print(f"Synthetic explorer: http://127.0.0.1:{server.server_port}\n{DISCLAIMER}", flush=True)
            try:
                server.serve_forever()
            except KeyboardInterrupt:
                pass
    elif args.command == "run":
        print(json.dumps(run_scenario(args.scenario, not args.without_approval, not args.without_ack), indent=2))
    else:
        if args.explain:
            from replay_explain import run_explanation
            raise SystemExit(run_explanation(args.file, MAX_BODY))
        try:
            if args.file.stat().st_size > MAX_BODY:
                raise ValueError("Export exceeds 262144 bytes")
            result = replay_result(json.loads(args.file.read_text()))
        except (ValueError, TypeError) as exc:
            parser.exit(2, str(exc) + "\n")
        print(json.dumps(result, indent=2))
        if not result["matches"]:
            raise SystemExit(1)


if __name__ == "__main__":
    main()

from __future__ import annotations

import hashlib
import json
import math
from collections.abc import Iterable
from dataclasses import asdict, dataclass, replace
from fractions import Fraction
from typing import Any

ZERO_HASH = "0" * 64


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def sha256_obj(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _finite_number(value: Any) -> bool:
    return type(value) is int or (type(value) is float and math.isfinite(value))


def _finite_time(value: Any) -> bool:
    return _finite_number(value)


class GateRejected(RuntimeError):
    def __init__(self, reason: str):
        super().__init__(reason)
        self.reason = reason


@dataclass(frozen=True)
class Aircraft:
    aircraft_id: str
    x_nm: float
    y_nm: float
    altitude_ft: float
    vx_nm_min: float
    vy_nm_min: float
    climb_ft_min: float = 0.0

    def projected(self, minutes: float) -> Aircraft:
        return replace(
            self,
            x_nm=self.x_nm + self.vx_nm_min * minutes,
            y_nm=self.y_nm + self.vy_nm_min * minutes,
            altitude_ft=self.altitude_ft + self.climb_ft_min * minutes,
        )


@dataclass(frozen=True)
class WorldState:
    version: int
    observed_at: float
    aircraft: tuple[Aircraft, ...]

    def __post_init__(self) -> None:
        # Keep the exact membership checked below even if a caller supplied a
        # mutable sequence or a one-shot iterator instead of a native tuple.
        object.__setattr__(self, "aircraft", tuple(self.aircraft))
        # Aircraft ids key every id-based operation (get, replace_aircraft,
        # advisory_safe's target exclusion). Duplicate ids would silently
        # break those invariants — e.g. advisory_safe skips id-twins, letting
        # an advisory that collides with a twin pass the gate — so malformed
        # states are rejected at construction instead of failing open.
        seen: set[str] = set()
        for aircraft in self.aircraft:
            if aircraft.aircraft_id in seen:
                raise ValueError(f"duplicate aircraft_id: {aircraft.aircraft_id!r}")
            seen.add(aircraft.aircraft_id)

    def to_dict(self) -> dict[str, Any]:
        return {
            "version": self.version,
            "observed_at": self.observed_at,
            "aircraft": [asdict(a) for a in sorted(self.aircraft, key=lambda x: x.aircraft_id)],
        }

    @property
    def world_hash(self) -> str:
        return sha256_obj(self.to_dict())

    def get(self, aircraft_id: str) -> Aircraft:
        for aircraft in self.aircraft:
            if aircraft.aircraft_id == aircraft_id:
                return aircraft
        raise KeyError(aircraft_id)

    def replace_aircraft(self, updated: Aircraft, observed_at: float) -> WorldState:
        values = tuple(updated if a.aircraft_id == updated.aircraft_id else a for a in self.aircraft)
        return WorldState(version=self.version + 1, observed_at=observed_at, aircraft=values)


@dataclass(frozen=True)
class Advisory:
    aircraft_id: str
    world_hash: str
    set_vx_nm_min: float
    set_vy_nm_min: float
    set_climb_ft_min: float
    issued_at: float
    expires_at: float
    rationale: str

    @property
    def advisory_hash(self) -> str:
        return sha256_obj(asdict(self))


@dataclass(frozen=True)
class Approval:
    advisory_hash: str
    decision: str
    approved_at: float
    approver: str


@dataclass(frozen=True)
class Ack:
    advisory_hash: str
    status: str
    acknowledged_at: float


class AuditLog:
    def __init__(self) -> None:
        self.events: list[dict[str, Any]] = []

    def append(self, kind: str, payload: dict[str, Any]) -> str:
        prev = self.events[-1]["event_hash"] if self.events else ZERO_HASH
        event = {"seq": len(self.events), "kind": kind, "payload": payload, "prev_hash": prev}
        event_hash = hashlib.sha256(prev.encode("ascii") + b"\n" + canonical_bytes(event)).hexdigest()
        event["event_hash"] = event_hash
        self.events.append(event)
        return event_hash

    @property
    def head(self) -> str:
        return self.events[-1]["event_hash"] if self.events else ZERO_HASH

    @staticmethod
    def verify(events: Iterable[dict[str, Any]]) -> bool:
        prev = ZERO_HASH
        for expected_seq, raw in enumerate(events):
            event = dict(raw)
            claimed = event.pop("event_hash", None)
            if event.get("seq") != expected_seq or event.get("prev_hash") != prev:
                return False
            actual = hashlib.sha256(prev.encode("ascii") + b"\n" + canonical_bytes(event)).hexdigest()
            if claimed != actual:
                return False
            prev = actual
        return True


@dataclass(frozen=True)
class SafetyPolicy:
    min_horizontal_nm: float = 5.0
    min_vertical_ft: float = 1000.0
    horizon_min: float = 5.0
    sample_step_min: float = 0.5
    max_state_age_sec: float = 10.0
    max_speed_nm_min: float = 6.0
    max_climb_ft_min: float = 3000.0

    @staticmethod
    def _linear_abs_unsafe_interval(offset: float, rate: float, limit: float, horizon: float) -> tuple[float, float] | None:
        """Open time interval in [0,horizon] where abs(offset + rate*t) < limit."""
        if limit <= 0.0 or horizon < 0.0:
            return None
        if rate == 0.0:
            return (0.0, horizon) if abs(offset) < limit else None
        t1, t2 = (-limit - offset) / rate, (limit - offset) / rate
        lo, hi = sorted((t1, t2))
        lo, hi = max(0.0, lo), min(horizon, hi)
        return (lo, hi) if lo < hi else None

    @staticmethod
    def _horizontal_unsafe_interval(dx: float, dy: float, dvx: float, dvy: float, limit: float, horizon: float) -> tuple[float, float] | None:
        """Open time interval in [0,horizon] where horizontal separation is below limit."""
        if limit <= 0.0 or horizon < 0.0:
            return None
        a = dvx * dvx + dvy * dvy
        b = 2.0 * (dx * dvx + dy * dvy)
        c = dx * dx + dy * dy - limit * limit
        if a == 0.0:
            return (0.0, horizon) if c < 0.0 else None
        disc = b * b - 4.0 * a * c
        if disc <= 0.0:
            return None
        root = math.sqrt(disc)
        lo, hi = sorted(((-b - root) / (2.0 * a), (-b + root) / (2.0 * a)))
        lo, hi = max(0.0, lo), min(horizon, hi)
        return (lo, hi) if lo < hi else None

    def _pair_conflict(self, a: Aircraft, b: Aircraft) -> bool:
        # Fail closed: a non-finite field (NaN/inf) means the separation is
        # unknown, so the pair is treated as conflicting rather than safe.
        # Without this, NaN comparisons silently evaluate False and an
        # aircraft with unknown state could pass the safety gate.
        for value in (
            a.x_nm, a.y_nm, a.altitude_ft, a.vx_nm_min, a.vy_nm_min, a.climb_ft_min,
            b.x_nm, b.y_nm, b.altitude_ft, b.vx_nm_min, b.vy_nm_min, b.climb_ft_min,
        ):
            if not _finite_number(value):
                return True
        h = self._horizontal_unsafe_interval(
            a.x_nm - b.x_nm, a.y_nm - b.y_nm,
            a.vx_nm_min - b.vx_nm_min, a.vy_nm_min - b.vy_nm_min,
            self.min_horizontal_nm, self.horizon_min,
        )
        if h is None:
            return False
        v = self._linear_abs_unsafe_interval(
            a.altitude_ft - b.altitude_ft, a.climb_ft_min - b.climb_ft_min,
            self.min_vertical_ft, self.horizon_min,
        )
        if v is None:
            return False
        return max(h[0], v[0]) < min(h[1], v[1])

    def state_has_conflict(self, state: WorldState) -> bool:
        values = list(state.aircraft)
        return any(self._pair_conflict(values[i], values[j]) for i in range(len(values)) for j in range(i + 1, len(values)))

    def conflicting_aircraft(self, state: WorldState) -> list[Aircraft]:
        """Aircraft that participate in at least one conflicting pair, sorted by id.

        The planner only proposes maneuvers for aircraft in this set: moving an
        uninvolved aircraft can never open separation for a conflict pair, and
        the gate alone cannot tell that an advisory is aimed at the wrong target.
        """
        values = sorted(state.aircraft, key=lambda x: x.aircraft_id)
        return [
            candidate
            for candidate in values
            if any(self._pair_conflict(candidate, other) for other in values if other.aircraft_id != candidate.aircraft_id)
        ]

    def advisory_safe(self, state: WorldState, advisory: Advisory) -> bool:
        if advisory.world_hash != state.world_hash:
            return False
        # A singleton has no pairwise checks to reject unknown candidate fields.
        if not all(_finite_number(value) for value in (
            advisory.set_vx_nm_min, advisory.set_vy_nm_min, advisory.set_climb_ft_min,
        )):
            return False
        if math.hypot(advisory.set_vx_nm_min, advisory.set_vy_nm_min) > self.max_speed_nm_min:
            return False
        if abs(advisory.set_climb_ft_min) > self.max_climb_ft_min:
            return False
        try:
            target = state.get(advisory.aircraft_id)
        except KeyError:
            return False
        if not all(_finite_number(value) for value in (target.x_nm, target.y_nm, target.altitude_ft)):
            return False
        candidate = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)
        return all(not self._pair_conflict(candidate, other) for other in state.aircraft if other.aircraft_id != candidate.aircraft_id)


class AdvisoryPlanner:
    """Deterministic synthetic planner; model adapters may propose alternatives, never bypass the frozen gate."""

    def __init__(self, policy: SafetyPolicy) -> None:
        self.policy = policy

    def _maneuver_candidates(self, target: Aircraft) -> Iterable[tuple[float, float, float]]:
        """Yield (vx, vy, climb) candidates in fixed priority order.

        Lateral-only variants come first to preserve the historical resolution
        preference; climb and speed variants follow so vertical-convergence
        conflicts (unresolvable laterally) still get a bounded safe advisory.
        Combined lateral+climb variants are tried last. Duplicates are skipped.
        Every candidate is still admitted only through ``advisory_safe``.
        """
        seen: set[tuple[float, float, float]] = set()

        def _emit(vx: float, vy: float, climb: float) -> Iterable[tuple[float, float, float]]:
            key = (vx, vy, climb)
            if key not in seen:
                seen.add(key)
                yield key

        speed_limit = self.policy.max_speed_nm_min
        vx = target.vx_nm_min
        if _finite_number(vx) and abs(vx) <= speed_limit:
            remaining_sq = max(0.0, speed_limit * speed_limit - vx * vx)
            vy_max = math.sqrt(remaining_sq)
            # Keep the boundary candidate inside policy after float rounding.
            while math.hypot(vx, vy_max) > speed_limit and vy_max > 0.0:
                vy_max = math.nextafter(vy_max, 0.0)
            old_menu = (2.0, -2.0, 3.0, -3.0, 0.0)
            lateral_values = (
                *(max(-vy_max, min(vy_max, vy)) for vy in old_menu),
                vy_max, -vy_max,
                vy_max / 2.0, -vy_max / 2.0,
                vy_max / 4.0, -vy_max / 4.0,
            )
            for vy in lateral_values:
                yield from _emit(vx, vy, target.climb_ft_min)
        for climb in (0.0, 1000.0, -1000.0, 2000.0, -2000.0, 3000.0, -3000.0):
            yield from _emit(target.vx_nm_min, target.vy_nm_min, climb)
        for dvx in (1.0, -1.0, 2.0, -2.0):
            yield from _emit(target.vx_nm_min + dvx, target.vy_nm_min, target.climb_ft_min)
        for vy in (2.0, -2.0, 3.0, -3.0):
            # Combined loop caps climb at +/-2000 (inside the gate's 3000 bound);
            # wider climb setpoints are already covered by the climb-only loop above.
            for climb in (0.0, 1000.0, -1000.0, 2000.0, -2000.0):
                yield from _emit(target.vx_nm_min, vy, climb)

    def plan(self, state: WorldState, now: float) -> list[Advisory]:
        if not self.policy.state_has_conflict(state):
            return []
        # Target selection: only aircraft that actually participate in a
        # conflict are maneuvered, highest id first (the historical default
        # target was always the highest id). Aiming at an uninvolved aircraft
        # produced gate-safe but useless advisories while the real conflict
        # persisted, so the planner now never targets outside the conflict set.
        targets = list(reversed(self.policy.conflicting_aircraft(state)))
        for target in targets:
            for vx, vy, climb in self._maneuver_candidates(target):
                advisory = Advisory(
                    aircraft_id=target.aircraft_id,
                    world_hash=state.world_hash,
                    set_vx_nm_min=vx,
                    set_vy_nm_min=vy,
                    set_climb_ft_min=climb,
                    issued_at=now,
                    expires_at=now + 8.0,
                    rationale="synthetic projected-separation recovery",
                )
                if self.policy.advisory_safe(state, advisory):
                    return [advisory]
        return []


class ControlRoom:
    def __init__(self, policy: SafetyPolicy | None = None) -> None:
        self.policy = policy or SafetyPolicy()
        self.audit = AuditLog()

    def _fresh(self, state: WorldState, now: float) -> None:
        if not _finite_time(state.observed_at) or not _finite_time(now):
            self.audit.append("reject", {"reason": "invalid_state_time"})
            raise GateRejected("invalid_state_time")
        if state.observed_at > now:
            self.audit.append("reject", {"reason": "future_state", "world_hash": state.world_hash})
            raise GateRejected("future_state")
        if type(now) is int or type(state.observed_at) is int:
            age = Fraction(now) - Fraction(state.observed_at)
        else:
            age = now - state.observed_at
        if age > self.policy.max_state_age_sec:
            self.audit.append("reject", {"reason": "stale_state", "world_hash": state.world_hash})
            raise GateRejected("stale_state")

    def screen_batch(self, state: WorldState, advisories: list[Advisory], now: float) -> list[str]:
        self._fresh(state, now)
        by_aircraft: dict[str, set[str]] = {}
        for advisory in advisories:
            by_aircraft.setdefault(advisory.aircraft_id, set()).add(advisory.advisory_hash)
        if any(len(hashes) > 1 for hashes in by_aircraft.values()):
            self.audit.append("reject", {"reason": "conflicting_recommendations", "world_hash": state.world_hash})
            raise GateRejected("conflicting_recommendations")
        hashes: list[str] = []
        for advisory in advisories:
            if not _finite_time(advisory.issued_at) or not _finite_time(advisory.expires_at):
                self.audit.append("reject", {"reason": "invalid_advisory_time", "aircraft_id": advisory.aircraft_id})
                raise GateRejected("invalid_advisory_time")
            if advisory.issued_at < state.observed_at or advisory.issued_at > now or advisory.expires_at < advisory.issued_at:
                self.audit.append("reject", {"reason": "invalid_advisory_time", "advisory_hash": advisory.advisory_hash})
                raise GateRejected("invalid_advisory_time")
            if advisory.world_hash != state.world_hash:
                self.audit.append("reject", {"reason": "world_hash_mismatch", "advisory_hash": advisory.advisory_hash})
                raise GateRejected("world_hash_mismatch")
            if now > advisory.expires_at:
                self.audit.append("reject", {"reason": "expired_advisory", "advisory_hash": advisory.advisory_hash})
                raise GateRejected("expired_advisory")
            if not self.policy.advisory_safe(state, advisory):
                self.audit.append("reject", {"reason": "unsafe_advisory", "advisory_hash": advisory.advisory_hash})
                raise GateRejected("unsafe_advisory")
            hashes.append(advisory.advisory_hash)
        self.audit.append("screen_pass", {"world_hash": state.world_hash, "advisory_hashes": hashes})
        return hashes

    def apply(self, state: WorldState, advisory: Advisory, approval: Approval | None, ack: Ack | None, now: float) -> WorldState:
        self.screen_batch(state, [advisory], now)
        if approval is None or approval.advisory_hash != advisory.advisory_hash or approval.decision != "approve":
            self.audit.append("reject", {"reason": "human_approval_required", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("human_approval_required")
        if not _finite_time(approval.approved_at):
            self.audit.append("reject", {"reason": "invalid_approval_time", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("invalid_approval_time")
        if approval.approved_at < advisory.issued_at or approval.approved_at > advisory.expires_at or approval.approved_at > now:
            self.audit.append("reject", {"reason": "invalid_approval_time", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("invalid_approval_time")
        self.audit.append("approval", asdict(approval))
        if ack is None:
            self.audit.append("reject", {"reason": "ack_missing", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("ack_missing")
        if ack.advisory_hash != advisory.advisory_hash or ack.status != "accepted":
            self.audit.append("reject", {"reason": "ack_invalid", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("ack_invalid")
        if not _finite_time(ack.acknowledged_at):
            self.audit.append("reject", {"reason": "invalid_ack_time", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("invalid_ack_time")
        if ack.acknowledged_at < approval.approved_at or ack.acknowledged_at < advisory.issued_at:
            self.audit.append("reject", {"reason": "invalid_ack_time", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("invalid_ack_time")
        if ack.acknowledged_at > advisory.expires_at or ack.acknowledged_at > now:
            self.audit.append("reject", {"reason": "ack_late", "advisory_hash": advisory.advisory_hash})
            raise GateRejected("ack_late")
        self.audit.append("ack", asdict(ack))
        target = state.get(advisory.aircraft_id)
        updated = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)
        new_state = state.replace_aircraft(updated, observed_at=now)
        self.audit.append("simulated_actuation", {
            "advisory_hash": advisory.advisory_hash,
            "before_world_hash": state.world_hash,
            "after_world_hash": new_state.world_hash,
        })
        return new_state


def baseline_apply_unchecked(state: WorldState, advisory: Advisory, now: float) -> WorldState:
    target = state.get(advisory.aircraft_id)
    updated = replace(target, vx_nm_min=advisory.set_vx_nm_min, vy_nm_min=advisory.set_vy_nm_min, climb_ft_min=advisory.set_climb_ft_min)
    return state.replace_aircraft(updated, observed_at=now)

"""Bounded literal differences for the local synthetic Explorer replay command."""
import copy
import json
import math
import os
from pathlib import Path
import stat
import sys

from scenarios import json_equivalent, replay_result, run_scenario

DIFFERENCE_LIMIT = 32
_MISSING = object()


def _json_type(value):
    if value is None:
        return "null"
    if type(value) is bool:
        return "boolean"
    if type(value) in (int, float):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    raise TypeError("Expected a JSON value")


def _side(value):
    if value is _MISSING:
        return {"present": False}
    return {"present": True, "type": _json_type(value), "value": value}


def _pointer(parent, key):
    return parent + "/" + str(key).replace("~", "~0").replace("/", "~1")


def _walk(expected, actual, pointer=""):
    if expected is _MISSING or actual is _MISSING:
        yield {
            "path": pointer,
            "kind": "unexpected" if expected is _MISSING else "missing",
            "expected": _side(expected),
            "actual": _side(actual),
        }
        return
    if json_equivalent(expected, actual):
        return
    expected_type, actual_type = _json_type(expected), _json_type(actual)
    if expected_type != actual_type:
        yield {"path": pointer, "kind": "type",
               "expected": _side(expected), "actual": _side(actual)}
    elif isinstance(expected, dict):
        for key in sorted(expected.keys() | actual.keys()):
            yield from _walk(expected.get(key, _MISSING),
                             actual.get(key, _MISSING), _pointer(pointer, key))
    elif isinstance(expected, list):
        for index in range(max(len(expected), len(actual))):
            left = expected[index] if index < len(expected) else _MISSING
            right = actual[index] if index < len(actual) else _MISSING
            yield from _walk(left, right, _pointer(pointer, index))
    else:
        yield {"path": pointer, "kind": "value",
               "expected": _side(expected), "actual": _side(actual)}


def explain_replay(value):
    """Return the ordinary replay reply plus at most 32 detached differences.

    Input is a finite decoded JSON export. This describes local reproduction,
    not provenance, causation or authority. Numeric comparison stays with the
    maintained Explorer comparator.
    """
    # Refuse nonfinite or excessively deep values before computing a report.
    json.dumps(value, allow_nan=False)
    actual = copy.deepcopy(value)
    reply = replay_result(actual)
    expected = run_scenario(**actual["request"])
    differences = []
    truncated = False
    for difference in _walk(expected, actual):
        if len(differences) == DIFFERENCE_LIMIT:
            truncated = True
            break
        differences.append(difference)
    return {**reply, "difference_limit": DIFFERENCE_LIMIT,
            "differences": differences, "differences_truncated": truncated}


def _finite_float(text):
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("Non-finite JSON numbers are not supported")
    return value


def _reject_constant(_text):
    raise ValueError("Non-finite JSON numbers are not supported")


def _read_export(path, max_bytes):
    # The descriptor check avoids consuming devices or pipes. It does not
    # promise exclusion of concurrent regular-file writers or directory races.
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NONBLOCK", 0)
    fd = os.open(path, flags)
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            raise ValueError("Replay explanation requires a regular file")
        with os.fdopen(fd, "rb") as source:
            fd = None
            raw = source.read(max_bytes + 1)
    finally:
        if fd is not None:
            os.close(fd)
    if len(raw) > max_bytes:
        raise ValueError(f"Export exceeds {max_bytes} bytes")
    return json.loads(raw.decode("utf-8"), parse_float=_finite_float,
                      parse_constant=_reject_constant)


def run_explanation(path: Path, max_bytes: int, stdout=None, stderr=None):
    """Deliver one complete prepared report; 0 match, 1 mismatch, 2 refusal."""
    output = sys.stdout if stdout is None else stdout
    errors = sys.stderr if stderr is None else stderr
    try:
        reply = explain_replay(_read_export(path, max_bytes))
        text = json.dumps(reply, ensure_ascii=False, allow_nan=False, indent=2) + "\n"
    except (OSError, ValueError, TypeError, RecursionError) as exc:
        print(f"Replay explanation rejected: {exc}", file=errors)
        return 2
    try:
        count = output.write(text)
        if type(count) is not int or count != len(text):
            raise OSError("Incomplete stdout write")
        output.flush()
    except (OSError, ValueError, UnicodeError) as exc:
        # The CLI exits immediately. Closing only its actual stdout suppresses
        # a second shutdown flush; caller-supplied streams remain caller-owned.
        if output is sys.stdout:
            try:
                output.close()
            except OSError:
                pass
        print(f"Replay explanation output failed: {exc}", file=errors)
        return 2
    return 0 if reply["matches"] else 1

import copy
import http.client
import json
import threading
import unittest

from explorer import Handler, ThreadingHTTPServer
from scenarios import SCENARIOS, replay_result, run_scenario
from towerops import AuditLog, canonical_bytes

EXPECTED = {"approved": None, "missing_approval": "human_approval_required", "missing_ack": "ack_missing",
            "late_ack": "ack_late", "stale_state": "stale_state", "stale_binding": "world_hash_mismatch",
            "wrong_ack": "ack_invalid", "expired": "expired_advisory"}


class ScenarioTests(unittest.TestCase):
    def test_all_cases_and_fixture_switches(self):
        for case in SCENARIOS:
            for approval in (False, True):
                for ack in (False, True):
                    with self.subTest(case=case, approval=approval, ack=ack):
                        result = run_scenario(case, approval, ack)
                        self.assertTrue(result["before_conflict"])
                        self.assertTrue(AuditLog.verify(result["audit_events"]))
                        self.assertTrue(replay_result(result)["matches"])
                        actuation = [e for e in result["audit_events"] if e["kind"] == "simulated_actuation"]
                        if case == "approved" and approval and ack:
                            self.assertEqual(result["outcome"], "simulated_actuation")
                            self.assertFalse(result["after_conflict"])
                            self.assertEqual(len(actuation), 1)
                            self.assertEqual(result["after"]["version"], result["before"]["version"] + 1)
                        else:
                            self.assertEqual(result["outcome"], "rejected")
                            self.assertEqual(result["before"], result["after"])
                            self.assertEqual(actuation, [])
                        if approval and ack:
                            self.assertEqual(result["rejection_reason"], EXPECTED[case])

    def test_replay_checks_whole_export(self):
        for case in SCENARIOS:
            original = run_scenario(case)
            for field in ("after", "audit_events", "disclaimer", "audit_head", "outcome"):
                with self.subTest(case=case, field=field):
                    changed = copy.deepcopy(original)
                    if field == "after":
                        changed[field]["version"] += 1
                    elif field == "audit_events":
                        changed[field][0]["payload"]["simulation_only"] = False
                    else:
                        changed[field] = "tampered"
                    self.assertFalse(replay_result(changed)["matches"])
        changed = run_scenario("approved")
        changed["audit_valid"] = 1
        self.assertFalse(replay_result(changed)["matches"])

    def test_javascript_numeric_roundtrip(self):
        original = run_scenario("approved")
        def integers(value):
            if type(value) is float and value.is_integer():
                return int(value)
            if isinstance(value, dict):
                return {k: integers(v) for k, v in value.items()}
            if isinstance(value, list):
                return [integers(v) for v in value]
            return value
        self.assertTrue(replay_result(integers(original))["matches"])
        changed = copy.deepcopy(original)
        changed["before"]["aircraft"][0]["vx_nm_min"] += 0.001
        self.assertFalse(replay_result(changed)["matches"])

    def test_no_baseline_changes_or_nondeterminism(self):
        self.assertEqual(canonical_bytes(run_scenario("approved")), canonical_bytes(run_scenario("approved")))

    def test_invalid_input(self):
        for value in (None, [], {}, {"format": "invalid"}):
            with self.subTest(value=value), self.assertRaises(ValueError):
                replay_result(value)
        with self.assertRaises(ValueError):
            run_scenario("unknown")
        with self.assertRaises(ValueError):
            run_scenario("approved", 1, True)  # type: ignore[arg-type]


class HTTPTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.server = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.thread = threading.Thread(target=cls.server.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()
        cls.server.server_close()
        cls.thread.join()

    def request(self, method, path, value=None, headers=None, raw=None):
        connection = http.client.HTTPConnection("127.0.0.1", self.server.server_port, timeout=5)
        body = json.dumps(value) if value is not None else raw
        supplied = {"Content-Type": "application/json"}
        supplied.update(headers or {})
        connection.request(method, path, body, supplied)
        response = connection.getresponse()
        status, content, response_headers = response.status, response.read(), dict(response.getheaders())
        connection.close()
        return status, content, response_headers

    def test_real_run_export_replay(self):
        status, content, _ = self.request("GET", "/api/scenarios")
        self.assertEqual(status, 200)
        self.assertEqual(len(json.loads(content)["scenarios"]), len(SCENARIOS))
        for case in SCENARIOS:
            with self.subTest(case=case):
                status, content, _ = self.request("POST", "/api/run", {"scenario": case, "include_approval": True, "include_ack": True})
                self.assertEqual(status, 200)
                exported = json.loads(content)
                self.assertEqual(exported["rejection_reason"], EXPECTED[case])
                status, content, _ = self.request("POST", "/api/replay", exported)
                self.assertEqual(status, 200)
                self.assertTrue(json.loads(content)["matches"])
                exported["after"]["version"] += 1
                self.assertFalse(json.loads(self.request("POST", "/api/replay", exported)[1])["matches"])

    def test_static_assets_and_unknown_routes(self):
        for path in ("/", "/app.js", "/style.css"):
            status, content, headers = self.request("GET", path)
            self.assertEqual(status, 200)
            self.assertGreater(len(content), 100)
            self.assertIn("frame-ancestors 'none'", headers["Content-Security-Policy"])
        for path in ("/towerops.py", "/../LICENSE", "/.git/config"):
            self.assertEqual(self.request("GET", path)[0], 404)

    def test_invalid_requests_fail(self):
        self.assertEqual(self.request("POST", "/api/run", {"scenario": "approved"})[0], 400)
        self.assertEqual(self.request("POST", "/api/run", raw="not-json")[0], 400)
        self.assertEqual(self.request("POST", "/api/run", raw='{"x": NaN}')[0], 400)
        self.assertEqual(self.request("POST", "/api/run", raw="[]")[0], 400)
        self.assertEqual(self.request("POST", "/api/run", raw="{}", headers={"Content-Type": "text/plain"})[0], 415)
        self.assertEqual(self.request("POST", "/api/run", raw="x" * 262145)[0], 413)
        self.assertEqual(self.request("POST", "/api/run", raw="{}")[0], 400)
        self.assertEqual(self.request("GET", "/", headers={"Host": "foreign.invalid"})[0], 403)
        self.assertEqual(self.request("POST", "/api/run", raw="{}", headers={"Origin": "https://foreign.invalid"})[0], 403)


